// ================== CONFIGURATION ==================
// Attribute KEYS (not display names) – visible under `attributes` in the output of "Get Employees"
const FIELD_TRAINING   = 'course-date-fire-protection-assistant';
const MONTHS           = 6;     // training is due when older than this many months
const EMPTY_IS_DUE     = true;  // also create a task when no training date is recorded?
const MARKER           = 'FST-EMP:'; // duplicate-protection marker in the task description
// ===================================================

// Deduplicate employees by ID (in case pagination returns an employee twice)
const employees = [...new Map(
  $('Get Employees').all().map(i => i.json).filter(e => e && e.id).map(e => [e.id, e])
).values()];
const openTasks = $input.all().map(i => i.json).filter(t => t && t.id);

// 1) Detect existing open / in-progress tasks
//    a) by the marker in title/description (backslashes/HTML are stripped first,
//       in case Teamanda stores the text as Markdown/HTML)
//    b) additionally by the title "Fire safety training due: <name>"
const clean = s => String(s ?? '').replace(/<[^>]*>/g, ' ').replace(/\\/g, '');
const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const markerRe = new RegExp(esc(MARKER) + '\\s*([A-Za-z0-9_-]+)', 'g');
const normTitle = s => clean(s).trim().toLowerCase().replace(/\s+/g, ' ');
const hasOpenTask = new Set();
const openTitles = new Set();
for (const t of openTasks) {
  const text = `${clean(t.title)}\n${clean(t.description)}`;
  for (const m of text.matchAll(markerRe)) hasOpenTask.add(m[1]);
  openTitles.add(normTitle(t.title));
}

// 2) Parse dates (ISO or dd.MM.yyyy)
function parseDate(v) {
  if (v === undefined || v === null || String(v).trim() === '') return null;
  const s = String(v).trim();
  for (const d of [DateTime.fromISO(s), DateTime.fromFormat(s, 'dd.MM.yyyy'), DateTime.fromFormat(s, 'd.M.yyyy')]) {
    if (d.isValid) return d.startOf('day');
  }
  return 'INVALID';
}
const cutoff = $now.startOf('day').minus({ months: MONTHS });

// 3) Evaluate
const out = [];
for (const e of employees) {
  const attrs = e.attributes ?? {};
  const name = e.fullName || e.displayName || e.id;
  const last = parseDate(attrs[FIELD_TRAINING]);

  if (last === 'INVALID') {
    out.push({ json: { canCreate: false, reason: `Unreadable date: "${attrs[FIELD_TRAINING]}"`, employeeId: e.id, employeeName: name } });
    continue;
  }
  const due = last === null ? EMPTY_IS_DUE : last < cutoff;
  if (!due) continue;
  const title = `Fire safety training due: ${name}`;
  if (hasOpenTask.has(e.id) || openTitles.has(normTitle(title))) continue; // task already exists

  const lastTxt = last ? last.toFormat('yyyy-MM-dd') : 'not recorded';
  out.push({ json: {
    canCreate: true,
    employeeId: e.id,
    employeeName: name,
    lastTraining: lastTxt,
    title,
    description:
      `The last fire safety training of ${name} was more than ${MONTHS} months ago (last training: ${lastTxt}).\n` +
      `Please arrange a new fire safety training.\n\n` +
      `[${MARKER}${e.id}] – do not remove (duplicate protection of the automation)`,
  } });
}
return out;
